import itertools,json
jobs='ABCDE'
slots=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
table=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
t={(a,b):table[i][j] for i,a in enumerate(jobs) for j,b in enumerate(jobs)}
def nominal(p):
 return sum(slots[a][i] for i,a in enumerate(p))+sum(t[a,b] for a,b in zip(p,p[1:]))
def incident(p,k):
 pos={a:p.index(a)+1 for a in jobs}
 if k=='rain':
  if pos['E']==2 or pos['D']==5:return None
  return nominal(p)+6*max(0,pos['A']-2)
 if k=='road':
  if pos['B']==5 or pos['D']==1:return None
  return nominal(p)+8*max(0,pos['C']-3)
 if pos['D']==4 or pos['C']==1:return None
 return nominal(p)+5*max(0,pos['E']-1)
perms=[''.join(p) for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
results=[]
for p in perms:
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
  if q.index('A')<q.index('D'):neighbors.append((q,4))
 repairs={};costs={}
 for k in ['rain','road','lift']:
  opts=[(incident(q,k)+fee,q) for q,fee in neighbors if incident(q,k) is not None]
  if not opts:break
  costs[k],repairs[k]=min(opts)
 if len(costs)==3:results.append((nominal(p)+max(costs.values()),p,repairs,costs))
results.sort()
best=results[0]
answer={'roster':best[1],'score':best[0],'repairs':best[2],'repair_costs':best[3],'feasible_count':len(results),'next_score':min(x[0] for x in results if x[0]>best[0])}
payload=json.dumps(answer)
# Independent evaluation: enumerate legal finals and use Hamming distance for exchange reachability.
parsed=json.loads(payload)
all_scores=[]
for p in perms:
 vals=[]
 for k in ['rain','road','lift']:
  candidates=[]
  for q in perms:
   distance=sum(a!=b for a,b in zip(p,q))
   if distance not in (0,2):continue
   positions={a:i for i,a in enumerate(q)}
   forbidden={'rain':[('E',1),('D',4)],'road':[('B',4),('D',0)],'lift':[('D',3),('C',0)]}[k]
   if any(positions[a]==i for a,i in forbidden):continue
   late_job,threshold,rate={'rain':('A',1,6),'road':('C',2,8),'lift':('E',0,5)}[k]
   base=sum(slots[q[i]][i] for i in range(5))+sum(table[jobs.index(q[i])][jobs.index(q[i+1])] for i in range(4))
   value=base+rate*max(0,positions[late_job]-threshold)+(4 if distance else 0)
   candidates.append((value,q))
  if not candidates:break
  vals.append(min(candidates)[0])
  if p==parsed['roster']:
   assert (parsed['repair_costs'][k],parsed['repairs'][k]) in candidates
   assert parsed['repair_costs'][k]==min(candidates)[0]
 if len(vals)==3:all_scores.append(nominal(p)+max(vals))
assert parsed['score']==min(all_scores)
assert parsed['feasible_count']==len(all_scores)
assert parsed['next_score']==min(s for s in all_scores if s>min(all_scores))
print(payload)
print('Verified all fields with independent final-roster enumeration; published nominal:',nominal(parsed['roster']))

