import itertools,json
jobs='ABCDE'; published='ACEBD'
slot=[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]
t=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def swap(p,i,j):
 q=list(p);q[i],q[j]=q[j],q[i];return ''.join(q)
dist={published:0}
for d in range(2):
 for p in [p for p in dist if dist[p]==d]:
  for i,j in itertools.combinations(range(5),2):
   dist.setdefault(swap(p,i,j),d+1)
def legal(p):return p.index('A')<p.index('D') and p[1]!='E' and p[4]!='D' and p[2]!='E'
def cost(p,d):
 return sum(slot[jobs.index(a)][i] for i,a in enumerate(p))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(p,p[1:]))+6*max(0,p.index('A')-1)+4*d+(5 if d==2 else 0)
classes={str(d):[(cost(p,d),p) for p,v in dist.items() if v==d and legal(p)] for d in range(3)}
best=min(x for xs in classes.values() for x in xs)
a={'roster':best[1],'score':best[0],'best_by_swaps':{k:min(xs)[0] if xs else None for k,xs in classes.items()},'feasible_by_swaps':{k:len(xs) for k,xs in classes.items()}}
payload=json.dumps(a)
# Independent distance via cycle decomposition on all 120 permutations.
check={str(d):[] for d in range(3)}
for q in itertools.permutations(jobs):
 p=''.join(q);perm=[published.index(x) for x in p];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=perm[j]
 d=5-cycles
 if d<=2 and legal(p):check[str(d)].append((cost(p,d),p))
r=json.loads(payload)
assert all(sorted(check[k])==sorted(classes[k]) for k in check)
assert (r['score'],r['roster'])==min(x for xs in check.values() for x in xs)
assert r['best_by_swaps']=={k:min(xs)[0] if xs else None for k,xs in check.items()}
assert r['feasible_by_swaps']=={k:len(xs) for k,xs in check.items()}
print(payload)
print('Verified by BFS distances and independent permutation-cycle distances.')

